// LINE ส่งหลายรูป = หลาย event ใน events[] -> แตกเป็นหลาย item เอาเฉพาะรูป
// + กันทำซ้ำด้วย webhookEventId (คีย์ที่ LINE แนะนำให้ใช้ตรวจ duplicate)

// ---- สวิตช์ทิ้ง retry ----
// false = ใช้ retry ได้ (กู้รูปที่ส่งครั้งแรกไม่สำเร็จ) — กันซ้ำด้วย webhookEventId อยู่แล้ว
// true  = ทิ้ง retry ทุกตัว (ใช้เฉพาะตอนโดน retry ถล่มจนต้องตัดวงจรชั่วคราว)
const SKIP_REDELIVERY = false;

const root = $input.first().json || {};
let events = [];
if (root.body && Array.isArray(root.body.events)) events = root.body.events;
else if (Array.isArray(root.events)) events = root.events;
else if (root.body && root.body.events) events = [].concat(root.body.events);

// รายการ event ที่ทำไปแล้ว — คงอยู่ข้าม execution (เฉพาะโหมด production/active)
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.doneKeys)) store.doneKeys = [];
const done = store.doneKeys;

const out = [];
const skipped = [];

for (const ev of events) {
  if (!ev || ev.type !== 'message' || !ev.message || ev.message.type !== 'image') continue;
  const mid = ev.message.id;
  if (!mid) continue;                                   // กัน messageId ว่าง -> ไม่ยิง download ให้ 400

  // คีย์กันซ้ำ: ใช้ webhookEventId ก่อน (นับ event เดียวกันแม้ LINE ส่งหลายรอบ)
  const key = ev.webhookEventId ? String(ev.webhookEventId) : ('MID:' + mid);
  const isRe = !!(ev.deliveryContext && ev.deliveryContext.isRedelivery === true);

  if (SKIP_REDELIVERY && isRe) { skipped.push(mid + ' = retry เก่า (ทิ้งตามสวิตช์)'); continue; }
  if (done.indexOf(key) !== -1) { skipped.push(mid + ' = event นี้ทำไปแล้ว'); continue; }

  done.push(key);                                       // จองทันที กันรอบถัดไปทำซ้ำ
  const src = ev.source || {};
  out.push({ json: {
    messageId: String(mid),
    replyToken: ev.replyToken || null,
    userId: src.userId || null,
    groupId: src.groupId || null,
    timestamp: ev.timestamp || null,
    webhookEventId: ev.webhookEventId || null,
    isRedelivery: isRe
  }});
}

if (done.length > 500) store.doneKeys = done.slice(-500);   // กัน static data บวม
if (skipped.length) console.log('ข้าม: ' + skipped.join(' | '));
// ไม่มีรูปใหม่ -> array ว่าง flow หยุดเอง (ไม่ยิง VLM ไม่เขียนชีต ไม่ตอบ LINE)
return out;

// ตัดสิน spreadsheet ปลายทาง: ถ้ามี test ID ใช้เลย, ถ้าลบออก(ว่าง) ค้นไฟล์เดือนปัจจุบัน
const testId = ($('Edit Fields: test spreadsheet ID').first().json.testSpreadsheetId || '').trim();

// เดือนปัจจุบัน Asia/Bangkok (ไม่ใช้ $now เพราะ TZ n8n อาจเป็น New_York)
const _ts = Number($('วนทีละรูป (Batch 1)').first().json.timestamp) || Date.now();
const bkk = new Date(_ts + 7*3600*1000);   // เวลาไทยจากเวลาที่ผู้ใช้ส่งรูป (ไม่ใช่เวลาที่ระบบรัน)
const y = bkk.getUTCFullYear();
const mm = String(bkk.getUTCMonth()+1).padStart(2,'0');
const titleSuffix = mm + '-' + y;               // เช่น 08-2026
const expectedName = 'FM-DEM-032-038-61 | ใบตรวจเช็คเครื่องจักรประจําวัน | ' + titleSuffix;

if (testId) {
  // มี test ID -> ใช้เลย ไม่ต้องค้น
  return [{ json: { spreadsheetId: testId, source: 'test-id', titleSuffix: titleSuffix, needSearch: false } }];
}
// ไม่มี ID -> ต้องค้นโฟลเดอร์
return [{ json: { spreadsheetId: null, source: 'search', titleSuffix: titleSuffix, expectedName: expectedName, needSearch: true } }];

// ตรวจผลค้น: ต้องเจอไฟล์ที่ title ลงท้าย titleSuffix เป๊ะ ไม่เจอ = หยุด error
const info = $('resolve spreadsheet').first().json;
const suffix = info.titleSuffix;
const expectedName = info.expectedName;

const hits = $input.all().map(i => i.json).filter(Boolean);
// กรองเฉพาะไฟล์ที่ชื่อ "ลงท้าย" ด้วย suffix (กันไฟล์ที่บังเอิญมี suffix กลางชื่อ)
const matches = hits.filter(f => {
  const name = f.name || f.title || '';
  return name.trim().endsWith(suffix);
});

if (matches.length === 0) {
  throw new Error('ไม่พบไฟล์ตรวจเช็คของเดือน ' + suffix + ' ในโฟลเดอร์ (คาดว่าชื่อ "' + expectedName + '") — หยุดทำงาน ไม่เขียนข้อมูลมั่ว ให้สร้างไฟล์เดือนนี้ก่อน (workflow สร้างไฟล์ควรรันต้นเดือน)');
}
// เจอหลายไฟล์ -> ใช้ตัวล่าสุด (createdTime/modifiedTime ใหม่สุด) + เตือน
let chosen = matches[0];
if (matches.length > 1) {
  chosen = matches.slice().sort((a,b) => {
    const ta = new Date(a.createdTime || a.modifiedTime || 0).getTime();
    const tb = new Date(b.createdTime || b.modifiedTime || 0).getTime();
    return tb - ta;
  })[0];
}
const id = chosen.id || chosen.fileId;
if (!id) throw new Error('เจอไฟล์เดือน ' + suffix + ' แต่ไม่มี id — หยุด');

return [{ json: {
  spreadsheetId: id, source: 'search-found', titleSuffix: suffix,
  matchedName: chosen.name || chosen.title,
  multipleWarning: matches.length > 1 ? ('เจอ '+matches.length+' ไฟล์ ใช้ตัวล่าสุด') : null
}}];

// ดึง binary รูปจากโหนดดาวน์โหลด (Code/Switch/noOp ทำ binary หาย)
const bin = $('ดาวน์โหลดภาพจาก LINE').first().binary;
return [{ json: $input.first().json, binary: bin }];

