// ดึง binary รูปจากโหนดดาวน์โหลด (Code/Switch/noOp ทำ binary หาย)
const bin = $('ดาวน์โหลดภาพจาก LINE').first().binary;
return [{ json: $input.first().json, binary: bin }];

// อ่านค่าจาก lcd_lines (call 2) แล้วสร้างเซลล์ครบทุกข้อ + ผู้ตรวจ
function safeJsonParse(text) {
  const cleaned = String(text).replace(/```json/gi,'').replace(/```/g,'').trim();
  const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
  if (s < 0 || e <= s) return { ok:false, err:'ไม่พบ JSON ในคำตอบ', data:null };
  const body = cleaned.slice(s, e+1);
  try { return { ok:true, err:null, data: JSON.parse(body) }; } catch (e1) {}
  // ซ่อม backslash ที่ไม่ตามด้วยตัว escape ที่ JSON ยอมรับ (LLM ชอบใส่ \T \x เกิน)
  const fixed = body.replace(/\\(?!["\\/bfnrtu])/g, '\\\\');
  try { return { ok:true, err:null, data: JSON.parse(fixed) }; }
  catch (e2) { return { ok:false, err:'parse ไม่ผ่านแม้ซ่อมแล้ว: '+e2.message, data:null }; }
}

const CFG = {
  sigma: {
    tabByLabel: { '72/1':'FM-DEM-035_BSD72-1', '72/2':'FM-DEM-035_BSD72-2' },
    itemRow: {1:9,2:10,3:11,4:12,5:13,6:14,7:15,8:16,9:17,10:18,11:20,12:21,13:22,14:23,15:24,16:26,17:27,18:28},
    inspectorRow: 30, numeric: {2:'temp',18:'bar'}, skip:[11,12,13,14],
    reTemp: /([\d.]+)\s*(?:°|º|\*|o)?\s*C\b/i, reBar: /([\d.]+)\s*bar/i
  },
  sp100: {
    tabByLabel: { 'SP100/1':'FM-DEM-036_SP100-1', 'SP100/2':'FM-DEM-036_SP100-2' },
    itemRow: {1:9,2:10,3:11,4:12,5:13,6:14,7:15,8:16,9:17,10:18,11:20,12:21,13:22,14:23,15:24,16:26,17:27,18:28},
    inspectorRow: 30, numeric: {2:'temp',18:'bar'}, skip:[11,12,13,14],
    reTemp: /AIR\s*T\s*:?\s*([\d.]+)/i, reBar: /AIR\s*P\s*:?\s*([\d.]+)/i
  }
};
const SPREADSHEET_ID = $('รวม spreadsheet ID').first().json.spreadsheetId;
// เทียบเดือนของคอลัมน์กับเดือนในชื่อไฟล์ที่ resolve มา (titleSuffix = MM-YYYY)
// แทน hardcode เดิม -> ไม่ต้องแก้เลขทุกเดือน และยังกันเขียนผิดเดือนได้
const _sfx = ($('รวม spreadsheet ID').first().json.titleSuffix || '').trim();  // เช่น '08-2026'
const _m = _sfx.match(/^(\d{1,2})-(\d{4})$/);
const SHEET_MONTH = _m ? parseInt(_m[1],10) : null;
const SHEET_YEAR  = _m ? parseInt(_m[2],10) : null;

function colLetter(n){let s='';while(n>0){const m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=Math.floor((n-1)/26);}return s;}
function pickText(j){if(typeof j==='string')return j;let raw='';const pref=['response','text','output','result','content','message','answer','generated_text','data'];for(const k of pref)if(typeof j[k]==='string'&&j[k].length>raw.length)raw=j[k];if(!raw)for(const k of Object.keys(j))if(typeof j[k]==='string'&&j[k].length>raw.length)raw=j[k];return raw;}

const _ts = Number($('วนทีละรูป (Batch 1)').first().json.timestamp) || Date.now();
const bkk = new Date(_ts + 7*3600*1000);   // เวลาไทยจากเวลาที่ผู้ใช้ส่งรูป (ไม่ใช่เวลาที่ระบบรัน)
const day=bkk.getUTCDate(), month=bkk.getUTCMonth()+1, year=bkk.getUTCFullYear();
const col=colLetter(13+day);

const info = $('route by label').first().json;   // screen + machine_label จาก call 1
const screen = info.screen, label = info.machine_label;
const cfg = CFG[screen];

const out = [];
for (const item of $input.all()) {
  const raw = pickText(item.json || {});
  const blockers = [];
  let temp=null, bar=null, lines=null;

  if (!cfg) blockers.push('ไม่มี CFG ของ screen '+JSON.stringify(screen));
  const tab = cfg ? cfg.tabByLabel[label] : null;
  if (cfg && !tab) blockers.push('ไม่มี tab ของ label '+JSON.stringify(label));

  const _pr = safeJsonParse(raw);
  let parsed = _pr.data;
  if (!_pr.ok) blockers.push(_pr.err);

  if (parsed && cfg) {
    lines = Array.isArray(parsed.lcd_lines) ? parsed.lcd_lines : [];
    if (!lines.length) blockers.push('ไม่มี lcd_lines');
    else {
      const j = lines.join('\n');
      const mT = j.match(cfg.reTemp), mB = j.match(cfg.reBar);
      if (!mT) blockers.push('แกะอุณหภูมิไม่ได้'); else temp=parseFloat(mT[1]);
      if (!mB) blockers.push('แกะแรงดันไม่ได้'); else bar=parseFloat(mB[1]);
    }
  }
  if (temp!==null && (temp<30||temp>130)) blockers.push('อุณหภูมิ '+temp+' นอกช่วง 30-130 C');
  if (bar!==null && (bar<0||bar>15)) blockers.push('แรงดัน '+bar+' นอกช่วง 0-15 bar');
  // ถ้าอ่านเดือนจากชื่อไฟล์ไม่ได้ = ข้ามการเช็ค (ไม่บล็อก) ; ถ้าได้ ต้องตรงกับวันนี้
  if (SHEET_MONTH!==null && (month!==SHEET_MONTH||year!==SHEET_YEAR)) blockers.push('วันนี้ '+month+'/'+year+' แต่ไฟล์เป็น '+String(SHEET_MONTH).padStart(2,'0')+'/'+SHEET_YEAR+' — ข้ามการเขียนกันลงผิดเดือน');

  const data=[], preview=[];
  if (blockers.length===0) {
    const numVals={temp:temp,bar:bar};
    const skip = cfg.skip || [];
    for (const it of Object.keys(cfg.itemRow).map(Number).sort((a,b)=>a-b)) {
      if (skip.indexOf(it)!==-1) continue;   // เว้นข้อ 11-14 (ช่องตัวเลขชั่วโมง ยังไม่มีรูป)
      const row=cfg.itemRow[it];
      let val;
      if (cfg.numeric[it]) { val=numVals[cfg.numeric[it]]; if(typeof val!=='number'){blockers.push('ข้อ '+it+' ต้องเป็นเลข');continue;} }
      else val='/';
      data.push({range:"'"+tab+"'!"+col+row, values:[[val]]});
      preview.push('ข้อ '+it+' '+col+row+'='+val);
    }
    data.push({range:"'"+tab+"'!"+col+cfg.inspectorRow, values:[['bot']]});
    preview.push('ผู้ตรวจ '+col+cfg.inspectorRow+'=bot');
  }
  const expected = cfg ? (Object.keys(cfg.itemRow).length - (cfg.skip||[]).length) + 1 : -1;
  const ready = blockers.length===0 && data.length===expected;

  out.push({ json: {
    ready:ready, blockers:blockers, machine:label, tab:tab||null,
    date_bkk:year+'-'+String(month).padStart(2,'0')+'-'+String(day).padStart(2,'0'),
    column:col, cells_count:data.length, preview:preview,
    spreadsheetId:SPREADSHEET_ID, data:data, ocr:{temperature:temp,bar:bar}
  }});
}
return out;

// ASB250: อ่าน PV (ghost-digit aware) -> ข้อ 19, เว้นข้อ 2, ที่เหลือ "/"
// CFG ต่อ label เพราะ chiller แต่ละรุ่นโครงต่างกัน (จำนวนข้อ/แถว/PV-item/ผู้ตรวจ)
function safeJsonParse(text) {
  const cleaned = String(text).replace(/```json/gi,'').replace(/```/g,'').trim();
  const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
  if (s < 0 || e <= s) return { ok:false, err:'ไม่พบ JSON ในคำตอบ', data:null };
  const body = cleaned.slice(s, e+1);
  try { return { ok:true, err:null, data: JSON.parse(body) }; } catch (e1) {}
  // ซ่อม backslash ที่ไม่ตามด้วยตัว escape ที่ JSON ยอมรับ (LLM ชอบใส่ \T \x เกิน)
  const fixed = body.replace(/\\(?!["\\/bfnrtu])/g, '\\\\');
  try { return { ok:true, err:null, data: JSON.parse(fixed) }; }
  catch (e2) { return { ok:false, err:'parse ไม่ผ่านแม้ซ่อมแล้ว: '+e2.message, data:null }; }
}

const CFG = {
  '250/3': { tab:'FM-DEM-032_ASB250-3',
    itemRow:{1:9,2:10,3:11,4:12,5:13,6:15,7:17,8:18,9:19,10:20,11:22,12:23,13:24,14:26,15:27,16:28,17:29,18:30,19:32,20:33},
    inspectorRow:35, pvItem:19, skip:[2] },
  'PF8/3': { tab:'FM-DEM-033_PF8-3',
    itemRow:{1:9,2:10,3:11,4:12,5:13,6:15,7:16,8:18,9:19,10:20,11:21,12:23,13:24,14:25,15:27,16:28,17:29,18:30,19:31,20:33,21:34},
    inspectorRow:36, pvItem:20, skip:[2] },
  'PF8/5': { tab:'FM-DEM-033_PF8-5',
    itemRow:{1:9,2:10,3:11,4:12,5:13,6:15,7:16,8:18,9:19,10:20,11:21,12:23,13:24,14:25,15:27,16:28,17:29,18:30,19:31,20:33,21:34},
    inspectorRow:36, pvItem:20, skip:[2] }
};
const SPREADSHEET_ID = $('รวม spreadsheet ID').first().json.spreadsheetId;
// เทียบเดือนของคอลัมน์กับเดือนในชื่อไฟล์ที่ resolve มา (titleSuffix = MM-YYYY)
// แทน hardcode เดิม -> ไม่ต้องแก้เลขทุกเดือน และยังกันเขียนผิดเดือนได้
const _sfx = ($('รวม spreadsheet ID').first().json.titleSuffix || '').trim();  // เช่น '08-2026'
const _m = _sfx.match(/^(\d{1,2})-(\d{4})$/);
const SHEET_MONTH = _m ? parseInt(_m[1],10) : null;
const SHEET_YEAR  = _m ? parseInt(_m[2],10) : null;

function colLetter(n){let s='';while(n>0){const m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=Math.floor((n-1)/26);}return s;}
function toNum(v){if(typeof v==='number'&&isFinite(v))return v;if(typeof v==='string'&&/^-?\d+(\.\d+)?$/.test(v.trim()))return parseFloat(v.trim());return null;}
function digitCount(n){return String(n).replace(/[^0-9]/g,'').length;}
function pickText(j){if(typeof j==='string')return j;let raw='';const pref=['response','text','output','result','content','message','answer','generated_text','data'];for(const k of pref)if(typeof j[k]==='string'&&j[k].length>raw.length)raw=j[k];if(!raw)for(const k of Object.keys(j))if(typeof j[k]==='string'&&j[k].length>raw.length)raw=j[k];return raw;}

const _ts = Number($('วนทีละรูป (Batch 1)').first().json.timestamp) || Date.now();
const bkk = new Date(_ts + 7*3600*1000);   // เวลาไทยจากเวลาที่ผู้ใช้ส่งรูป (ไม่ใช่เวลาที่ระบบรัน)
const day=bkk.getUTCDate(), month=bkk.getUTCMonth()+1, year=bkk.getUTCFullYear();
const col=colLetter(13+day);

const info = $('route by label').first().json;
const label = info.machine_label;
const cfg = CFG[label];
const tab = cfg ? cfg.tab : null;
const ITEM_ROW = cfg ? cfg.itemRow : {};
const INSPECTOR_ROW = cfg ? cfg.inspectorRow : null;
const PV_ITEM = cfg ? cfg.pvItem : null;
const SKIP_ITEMS = cfg ? cfg.skip : [];

const out = [];
for (const item of $input.all()) {
  const raw = pickText(item.json.output || {});
  const blockers = [];
  let pv=null;

  if (!cfg) blockers.push('ไม่มี CFG/tab ของ '+JSON.stringify(label));

  const _pr = safeJsonParse(raw);
  let parsed = _pr.data;
  if (!_pr.ok) blockers.push(_pr.err);

  if (parsed) {
    pv = toNum(parsed.pv);
    if (pv===null) blockers.push('pv อ่านเป็นตัวเลขไม่ได้: '+JSON.stringify(parsed.pv));
    // ghost digit guard: นับจาก pv_raw (string จากจอ ยังมี .0 ครบ) ไม่ใช่จาก pv (number ที่ .0 หาย)
    // pv=29.0 ใน JSON = number 29 -> .0 หายตั้งแต่ parse แต่ pv_raw="29.0" ยังครบ นับได้ 3 segment
    const pd = toNum(parsed.pv_digits);
    const pvRaw = (parsed.pv_raw == null) ? '' : String(parsed.pv_raw);
    const rawDigits = pvRaw.replace(/[^0-9]/g, '').length;
    if (pv!==null && pd!==null && pvRaw && rawDigits!==pd)
      blockers.push('PV ขัดกันเอง: จอสว่าง '+pd+' หลัก แต่ pv_raw "'+pvRaw+'" มี '+rawDigits+' หลัก — น่าจะติด ghost digit');
    // sanity: pv_raw กับ pv ต้องเป็นค่าเดียวกัน (กันโมเดลส่งไม่ตรงกันเอง)
