  if (parsed) {
    const top = typeof parsed.top_line==='string' ? parsed.top_line : '';
    const slotRaw = typeof parsed.slot_row==='string' ? parsed.slot_row : '';

    // แรงดัน: ยึด "ON AUTO ... bar" ไม่ใช่ bar ตัวแรก
    const mB = top.match(/ON\s*AUTO\s+([\d.]+)\s*bar/i) || top.match(/([\d.]+)\s*bar/i);
