    slots = parseSlotRow(slotRaw);
    if (slots.length!==4) blockers.push('slot_row ต้องมี 4 ตำแหน่ง แต่ได้ '+slots.length+': "'+slotRaw+'"');
    const unknown = slots.filter(function(s){return s.state==='unknown';}).map(function(s){return s.pos;});
    if (unknown.length) blockers.push('slot อ่านไม่ชัดที่ตำแหน่ง '+JSON.stringify(unknown)+' — ตกทั้งรูป ให้คนเช็ค');

    if (blockers.length===0) {
      // ดูแค่ตำแหน่ง 1-3 เท่านั้น (มีจริงแค่ NO.1-3) — ตำแหน่ง 4 ไม่สนใจ ไม่ว่าอ่านเป็น X หรือเลข
      // เหตุผล: ตำแหน่ง 4 เป็นที่ที่โมเดลอ่านกากบาทที่ทับเลขไม่เห็นบ่อยสุด และไม่มีแท็บรองรับอยู่แล้ว
      // ตำแหน่ง n (1-3) เป็นเลข = เขียน NO.n, เป็น X = ข้าม
      writeTabs = slots.filter(function(s){return s.pos<=3 && s.state==='number';}).map(function(s){return s.pos;});
      if (writeTabs.length===0) blockers.push('ไม่มี slot ไหนทำงาน (ตำแหน่ง 1-3 โดน X หมด) — ไม่มีอะไรให้เขียน');
    }
