  if (SHEET_MONTH!==null && (month!==SHEET_MONTH||year!==SHEET_YEAR)) blockers.push('วันนี้ '+month+'/'+year+' แต่ไฟล์เป็น '+String(SHEET_MONTH).padStart(2,'0')+'/'+SHEET_YEAR+' — ข้ามการเขียนกันลงผิดเดือน');

  // สร้างเซลล์ทุกแท็บที่ทำงาน: ข้อ 8 = bar, ที่เหลือ /, ผู้ตรวจ = bot
  const data=[], preview=[];
  if (blockers.length===0) {
    for (const pos of writeTabs) {
      const tab = SLOT_TAB[pos];
