    }
  }
  const expected = writeTabs.length * (Object.keys(BOOSTER_ITEM_ROW).length + 1);
  const ready = blockers.length===0 && data.length===expected && data.length>0;

  out.push({ json: {
    ready:ready, blockers:blockers, machine:'Booster',
    write_tabs: writeTabs.map(function(p){return SLOT_TAB[p].slice(-5);}),
    slot_row: parsed ? parsed.slot_row : null,
    slots: slots.map(function(s){return s.pos+':'+s.state;}),
