function safeJsonParse(text) {

  const cleaned = String(text)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');

  if (s < 0 || e <= s) {
    return {
      ok: false,
      err: 'ไม่พบ JSON ในคำตอบ',
      data: null
    };
  }

  const body = cleaned.slice(s, e + 1);

  try {
    return {
      ok: true,
      err: null,
      data: JSON.parse(body)
    };
  } catch (e1) {}

  const fixed =
    body.replace(
      /\\(?!["\\/bfnrtu])/g,
      '\\\\'
    );

  try {
    return {
      ok: true,
      err: null,
      data: JSON.parse(fixed)
    };
  } catch (e2) {

    return {
      ok: false,
      err:
        'parse ไม่ผ่านแม้ซ่อมแล้ว: ' +
        e2.message,
      data: null
    };
  }
}


