function itemFromHeading(h) {

  const s =
    String(h == null ? '' : h)
      .toLowerCase();


  if (
    s.indexOf('separator') !== -1 ||
    s.indexOf('seperator') !== -1
  ) {
    return 12;
  }


  if (
    s.indexOf('air') !== -1 &&
    s.indexOf('filter') !== -1
  ) {
    return 14;
  }


  if (
    s.indexOf('oil') !== -1 &&
    s.indexOf('filter') !== -1
  ) {
    return 11;
  }


  if (
    s.indexOf('oil') !== -1 &&
    s.indexOf('change') !== -1
  ) {
    return 13;
  }


  return null;
}


