function colLetter(n) {

  let s = '';

  while (n > 0) {

    const m =
      (n - 1) % 26;

    s =
      String.fromCharCode(65 + m) +
      s;

    n =
      Math.floor((n - 1) / 26);
  }

  return s;
}


function toInt(v) {

  if (
    typeof v === 'number' &&
    isFinite(v) &&
    Math.floor(v) === v
  ) {
    return v;
  }

  if (
    typeof v === 'string' &&
    /^-?\d+$/.test(v.trim())
  ) {
    return parseInt(v.trim(), 10);
  }

  return null;
}


function toNum(v) {

  if (
    typeof v === 'number' &&
    isFinite(v)
  ) {
    return v;
  }

  if (
    typeof v === 'string' &&
    /^-?\d+(\.\d+)?$/.test(v.trim())
  ) {
    return parseFloat(v.trim());
  }

  return null;
}


function pickText(j) {

  if (typeof j === 'string') {
    return j;
  }

  let raw = '';

  const pref = [
    'response',
    'text',
    'output',
    'result',
    'content',
    'message',
    'answer',
    'generated_text',
    'data'
  ];


  for (const k of pref) {

    if (
      typeof j[k] === 'string' &&
      j[k].length > raw.length
    ) {
      raw = j[k];
    }
  }


  if (!raw) {

    for (const k of Object.keys(j)) {

      if (
        typeof j[k] === 'string' &&
        j[k].length > raw.length
      ) {
        raw = j[k];
      }
    }
  }

  return raw;
}


