function rawMismatch(rawVal, num) {

  const s =
    rawVal == null
      ? ''
      : String(rawVal)
          .replace(/\s|h/gi, '');


  if (!s) {
    return null;
  }


  if (!/^-?\d+$/.test(s)) {

    return (
      'ค่า "' +
      s +
      '" ไม่ใช่จำนวนเต็ม'
    );
  }


  if (
    num !== null &&
    parseInt(s, 10) !== num
  ) {

    return (
      'ค่าดิบ (' +
      s +
      ') กับตัวเลข (' +
      num +
      ') ไม่ตรงกัน'
    );
  }


  return null;
}


