    if (rem === null) {

      blockers.push(
        'remaining_h อ่านเป็นจำนวนเต็มไม่ได้: ' +
        JSON.stringify(
          parsed.remaining_h
        )
      );
    }


    const e1 =
      rawMismatch(
        parsed.remaining_raw,
        rem
      );


    if (e1) {

      blockers.push(
        'ชั่วโมงคงเหลือ: ' +
        e1
      );
    }


    if (
      lim !== null &&
      lim <= 0
    ) {

      blockers.push(
        'limit_h ' +
        lim +
        ' ควรเป็นจำนวนบวก'
      );
    }


    if (
      rem !== null &&
      lim !== null &&
      rem > lim
    ) {

      blockers.push(
        'remaining_h (' +
        rem +
        ') มากกว่า limit_h (' +
        lim +
        ')'
      );
    }


    if (
      rem !== null &&
      (
        rem < REM_MIN ||
        rem > REM_MAX
      )
    ) {

      blockers.push(
        'remaining_h ' +
        rem +
        ' นอกช่วง ' +
        REM_MIN +
        ' ถึง ' +
        REM_MAX
      );
    }


    // ------------------------
    // Temperature = ข้อ 2
    // ------------------------

    if (temp === null) {

      blockers.push(
        'temperature_c อ่านเป็นตัวเลขไม่ได้: ' +
        JSON.stringify(
          parsed.temperature_c
        )
      );
    }


    if (
      temp !== null &&
      (
        temp < TEMP_MIN ||
        temp > TEMP_MAX
      )
    ) {

      blockers.push(
        'Temperature ' +
        temp +
        ' นอกช่วง ' +
        TEMP_MIN +
        '-' +
        TEMP_MAX +
        ' C'
      );
    }


    // raw temperature cross-check

    const tempRaw =
      parsed.temperature_raw == null
        ? ''
        : String(
            parsed.temperature_raw
          ).trim();


    if (
      temp !== null &&
      tempRaw &&
      parseFloat(tempRaw) !== temp
    ) {

      blockers.push(
        'temperature_raw (' +
        tempRaw +
        ') กับ temperature_c (' +
        temp +
        ') ไม่ตรงกัน'
      );
    }


    // ------------------------
    // Pressure = ข้อ 18
    // ------------------------

    if (bar === null) {

      blockers.push(
        'pressure_bar อ่านเป็นตัวเลขไม่ได้: ' +
        JSON.stringify(
          parsed.pressure_bar
        )
      );
    }


    if (
      bar !== null &&
      (
        bar < BAR_MIN ||
        bar > BAR_MAX
      )
    ) {

      blockers.push(
        'Pressure ' +
        bar +
        ' นอกช่วง ' +
        BAR_MIN +
        '-' +
        BAR_MAX +
        ' bar'
      );
    }


    const barRaw =
      parsed.pressure_raw == null
        ? ''
        : String(
            parsed.pressure_raw
          ).trim();


    if (
      bar !== null &&
      barRaw &&
      parseFloat(barRaw) !== bar
    ) {

      blockers.push(
        'pressure_raw (' +
        barRaw +
        ') กับ pressure_bar (' +
        bar +
        ') ไม่ตรงกัน'
      );
    }


// ============================================================
// WRITE
// ============================================================

    if (
      blockers.length === 0
    ) {

      // ข้อ 2 Temperature

      data.push({

        range:
          "'" +
          tab +
          "'!" +
          col +
          cfg.itemRow[2],

        values: [[temp]]
      });


      preview.push(
        'ข้อ 2 ' +
        col +
        cfg.itemRow[2] +
        '=' +
        temp
      );


      // Service item 11-14

      data.push({

        range:
          "'" +
          tab +
          "'!" +
          col +
          cfg.itemRow[itemNo],

        values: [[rem]]
      });


      preview.push(
        'ข้อ ' +
        itemNo +
        ' (' +
        heading +
        ') ' +
        col +
        cfg.itemRow[itemNo] +
        '=' +
        rem
      );


      // ข้อ 18 Pressure

      data.push({

        range:
          "'" +
          tab +
          "'!" +
          col +
          cfg.itemRow[18],

        values: [[bar]]
      });


      preview.push(
        'ข้อ 18 ' +
        col +
        cfg.itemRow[18] +
        '=' +
        bar
      );
    }
  }


// ============================================================
// SP100 BEEN USED
// เหมือนเดิม ไม่เปลี่ยน
// ============================================================

  if (
    parsed &&
    cfg &&
    fmt === 'beenused'
  ) {

    const oil =
      toInt(
        parsed.oil_filter_h
      );


    const oa =
      toInt(
        parsed.oa_filter_h
      );


    const air =
      toInt(
        parsed.air_filter_h
      );


    ocr = {

      format: fmt,

      oil_filter_h:
        oil,

      oa_filter_h:
        oa,

      air_filter_h:
        air
    };


    if (oil === null) {

      blockers.push(
        'OIL FILTER อ่านเป็นจำนวนเต็มไม่ได้'
      );
    }


    if (oa === null) {

      blockers.push(
        'O-A FILTER อ่านเป็นจำนวนเต็มไม่ได้'
      );
    }


    if (air === null) {

      blockers.push(
        'AIR FILTER อ่านเป็นจำนวนเต็มไม่ได้'
      );
    }


    const eo =
      rawMismatch(
        parsed.oil_filter_raw,
        oil
      );

    if (eo) {
      blockers.push(
        'OIL FILTER: ' + eo
      );
    }


    const ea =
      rawMismatch(
        parsed.oa_filter_raw,
        oa
      );

    if (ea) {
      blockers.push(
        'O-A FILTER: ' + ea
      );
    }


    const er =
      rawMismatch(
        parsed.air_filter_raw,
        air
      );

    if (er) {
      blockers.push(
        'AIR FILTER: ' + er
      );
    }


    if (
      oil !== null &&
      oa !== null &&
      air !== null &&
      !(
        oil === oa &&
        oa === air
      )
    ) {

      blockers.push(
        '3 แถวไม่เท่ากัน'
      );
    }


    if (
      oil !== null &&
      (
        oil < USED_MIN ||
        oil > USED_MAX
      )
    ) {

      blockers.push(
        'ชั่วโมงที่ใช้แล้ว ' +
        oil +
        ' นอกช่วง'
      );
    }


    if (
      blockers.length === 0
    ) {

      for (
        const it of [
          11,
          12,
          13,
          14
        ]
      ) {

        data.push({

          range:
            "'" +
            tab +
            "'!" +
            col +
            cfg.itemRow[it],

          values:
            [[oil]]
        });


        preview.push(
          'ข้อ ' +
          it +
          ' ' +
          col +
          cfg.itemRow[it] +
          '=' +
          oil
        );
      }
    }
  }


// ============================================================
// INSPECTOR
// ============================================================

  if (
    blockers.length === 0 &&
    cfg
  ) {

    data.push({

      range:
        "'" +
        tab +
        "'!" +
        col +
        cfg.inspectorRow,

      values:
        [['bot']]
    });


    preview.push(
      'ผู้ตรวจ ' +
      col +
      cfg.inspectorRow +
      '=bot'
    );
  }


// ============================================================
// EXPECTED
//
// 72: Temp + Service + Pressure + Inspector = 4
// SP100: 4 Service + Inspector = 5
// ============================================================

  const expected =
    fmt === 'beenused'
      ? 5
      : 4;


  const ready =
    blockers.length === 0 &&
    data.length === expected;


  out.push({

    json: {

      ready:
        ready,

      blockers:
        blockers,

      machine:
        label,

      tab:
        tab || null,

      date_bkk:
        year +
        '-' +
        String(month)
          .padStart(2, '0') +
        '-' +
        String(day)
          .padStart(2, '0'),

      column:
        col,

      cells_count:
        data.length,

      skipped_items:
        [],

      preview:
        preview,

      spreadsheetId:
        SPREADSHEET_ID,

      data:
        data,

      ocr:
        ocr
    }
  });
}


return out;

// กัน "/" ทับค่าจริงที่มีอยู่แล้วใน Google Sheet
// กติกา:
// 1) ถ้าค่าที่จะเขียน = "/" และ cell ปัจจุบันมี "ค่าจริง" -> ข้าม
// 2) ถ้า cell ปัจจุบันว่าง หรือเป็น "-" -> เขียน "/" ได้
// 3) ค่าจริงจาก OCR (ตัวเลข/ข้อความอื่น) เขียนได้เสมอ และสามารถทับ "/" หรือ "-" เดิมได้
// 4) "bot" ผู้ตรวจเขียนได้ตามเดิม

const plan = $('เติม / เฉพาะช่องที่กำหนด').first().json;
const planned = Array.isArray(plan.data) ? plan.data : [];

const resp = $input.first().json || {};

const valueRanges =
  Array.isArray(resp.valueRanges)
    ? resp.valueRanges
    : (resp.body && Array.isArray(resp.body.valueRanges)
        ? resp.body.valueRanges
        : []);

function plannedValue(d) {
  return d && d.values && d.values[0]
    ? d.values[0][0]
    : undefined;
}

function existingValue(vr) {
  if (!vr || !Array.isArray(vr.values) || !vr.values.length) {
    return undefined;
  }

  if (!Array.isArray(vr.values[0]) || !vr.values[0].length) {
    return undefined;
  }

  return vr.values[0][0];
}

// ถือว่าเป็น "ช่องว่าง" ถ้า:
// - ไม่มีค่า
// - เป็น ""
// - เป็น "-"
function isEmpty(v) {
  if (v === undefined || v === null) return true;

  const s = String(v).trim();

  return s === '' || s === '-';
}

const keep = [];
const skippedSlash = [];

for (let i = 0; i < planned.length; i++) {

  const d = planned[i];

  const next = plannedValue(d);
  const current = existingValue(valueRanges[i]);

  // ถ้ากำลังจะเขียน "/"
  if (next === '/') {

    // มีค่าจริงอยู่แล้ว -> ห้าม "/" ทับ
    if (!isEmpty(current)) {
      skippedSlash.push({
        range: d.range,
        existing: current
      });

      continue;
    }
  }

  // ค่าจริงจาก OCR หรือ "/" ที่ช่องเดิมว่าง/เป็น "-"
  keep.push(d);
}


// Safety:
// Google Sheets ต้องคืน valueRanges ครบทุกช่องที่ขอ
// ถ้าไม่ครบ หยุดเพื่อไม่เดาสถานะของ cell
if (valueRanges.length !== planned.length) {

  return [{
    json: {
      ...plan,

      ready: false,

      blockers: [
        ...(plan.blockers || []),
        'อ่านค่าปัจจุบันจากชีตไม่ครบ: ขอ ' +
        planned.length +
        ' ช่อง แต่ได้ ' +
        valueRanges.length +
        ' ช่อง'
      ],

      data: []
    }
  }];
}


return [{
  json: {
    ...plan,

    data: keep,

    cells_count: keep.length,

    skipped_slash_count: skippedSlash.length,

    skipped_slash: skippedSlash,

    ready: plan.ready === true
  }
}];
